      "id": "H1",
      "texto": "El servicio de urgencias del Hospital San Rafael, en Altamira del Río, dejó de atender.",
      "tipo": "dato",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H2",
      "texto": "Las urgencias del Hospital San Rafael de Altamira del Río fueron cerradas.",
      "tipo": "dato",
      "paginas": ["P3"]
    },
    {
      "id": "H3",
      "texto": "La falta de médicos para completar los turnos obligó a suspender la atención.",
      "tipo": "dato",
      "paginas": ["P3", "P4"]
    },
    {
      "id": "H4",
      "texto": "Quienes necesiten atención de urgencia deberán ir a Santa Brígida, a 50 kilómetros.",
      "tipo": "dato",
      "paginas": ["P2", "P3", "P4"]
    },
    {
      "id": "H5",
      "texto": "Las remisiones se están haciendo hacia Santa Brígida, que queda a 50 kilómetros.",
      "tipo": "dato",
      "paginas": ["P3"]
    },
    {
      "id": "H6",
      "texto": "Una enfermera que pidió reserva dijo que a varios médicos les deben tres meses de salario.",
      "tipo": "dato",
      "paginas": ["P3", "P4"]
    },
    {
      "id": "H7",
      "texto": "Por las urgencias pasaban alrededor de 120 personas cada día.",
      "tipo": "dato",
      "paginas": ["P3", "P4"]
    }
  ]
}
